use types::*;

const DEPTH: usize = 20_000;

fn array_leaf(mut value: &ArrayTree) -> (&str, usize) {
    let mut depth = 0;
    while let Some(child) = value.children().as_slice().first() { value = child; depth += 1; }
    (value.label(), depth)
}

#[test]
fn array_only_recursive_schema_has_a_stack_safe_native_lifecycle() {
    let mut value = ArrayTree::try_new(ArrayTreeChildren::try_new(Vec::new()).expect("empty leaf children").value, "leaf".to_owned()).expect("leaf").value;
    for _ in 0..DEPTH {
        value = ArrayTree::try_new(ArrayTreeChildren::try_new(vec![value]).expect("recursive children").value, "branch".to_owned()).expect("recursive array branch").value;
    }
    let mut source = r#"{"label":"branch","children":["#.repeat(DEPTH);
    source.push_str(r#"{"label":"leaf","children":[]}"#);
    source.push_str(&"]}".repeat(DEPTH));
    let decoded = decode_array_tree(&source, Binding::Ipc).expect("array-only recursive decode").value;
    assert_eq!(array_leaf(&decoded), ("leaf", DEPTH));
    assert_eq!(value, decoded);
    let cloned = value.clone();
    assert_eq!(cloned, decoded);
    assert!(format!("{cloned:?}").contains("leaf"));
    let encoded = encode_array_tree(&cloned, Binding::Http);
    let again = decode_array_tree(&encoded, Binding::Http).expect("array-only round trip").value;
    assert_eq!(array_leaf(&again), ("leaf", DEPTH));
    assert_eq!(again, value);
    let (children, _) = cloned.into_parts();
    let mut detached = children.into_vec();
    detached.clear();
    assert_eq!(array_leaf(&value), ("leaf", DEPTH));
    let different = decode_array_tree(&source.replace("\"leaf\"", "\"different\""), Binding::Ipc).expect("different deep array leaf").value;
    assert_ne!(different, value);
    drop((value, decoded, again, different));
}

