#[test]
fn long_acyclic_declaration_chain_has_a_native_lifecycle_outside_any_scc() {
    let constructed = construct_chain();
    let mut source = r#"{"child":"#.repeat(255);
    source.push_str(r#"{"leaf":"leaf"}"#);
    source.push_str(&"}".repeat(255));
    let decoded = decode_chain000(&source, Binding::Ipc).expect("acyclic declaration chain decode").value;
    assert_eq!(chain_leaf(&constructed), "leaf");
    assert_eq!(chain_leaf(&decoded), "leaf");
    assert_eq!(constructed, decoded);
    let cloned = decoded.clone();
    assert_eq!(cloned, constructed);
    assert!(format!("{cloned:?}").contains("leaf"));
    let encoded = encode_chain000(&cloned, Binding::Http);
    let again = decode_chain000(&encoded, Binding::Http).expect("acyclic declaration chain round trip").value;
    assert_eq!(chain_leaf(&again), "leaf");
    assert_eq!(again, constructed);
    let different = decode_chain000(&source.replace("\"leaf\":\"leaf\"", "\"leaf\":\"different\""), Binding::Ipc).expect("different acyclic leaf").value;
    assert_ne!(different, constructed);
    drop((constructed, decoded, cloned, again, different));
}
